    solver.add(name["Eric"] == lunch["grilled cheese"])
    solver.add(mother["Holly"] + 1 == name["Alice"])
    solver.add(next_to(mother["Holly"], lunch["stew"]))
    solver.add(name["Alice"] == style["ranch"])
    solver.add(name["Carol"] != 5)
    solver.add(lunch["stir fry"] == color["purple"])
