all_vars = [Eric, Arnold, Prince, PallMall, Dane, Brit, Associate, HighSchool, FordF150, TeslaModel3]
for var in all_vars:
    solver.add(var >= 1, var <= 2)

solver.add(Distinct(Eric, Arnold))
solver.add(Distinct(Prince, PallMall))
solver.add(Distinct(Dane, Brit))
solver.add(Distinct(Associate, HighSchool))
solver.add(Distinct(FordF150, TeslaModel3))

